#!/usr/bin/env python3
"""Compare regenerated files with their committed blobs, exactly.

Fault-window re-check W2-3, part B (sub-agent w2-3b), 2026-10-15.

For each repository-relative path, the regenerated file under ``--tree`` is
compared with ``git show <commit>:<path>`` byte for byte (sha256). Where the
bytes differ, JSON files are compared leaf by leaf, CSV files cell by cell, and
other text line by line, and every differing location is listed. Leaves whose
key matches an ``--ignore-key`` regex are set aside (and counted), so a
timestamp or machine path can be named rather than silently skipped. The tool
also reports whether today's file (``--today`` revision) is the generating
commit's blob.

Usage:
    compare_files.py --repo WT --tree TREE --commit C --out OUT.json \
        [--ignore-key REGEX ...] (--paths P ... | --paths-file F)

--substitute OLD=NEW rewrites the regenerated bytes before comparing (for
example the replay tree root back to the original run root), so a machine
path is shown to differ ONLY in its root; such files are reported as
BYTE-IDENTICAL-AFTER-SUBSTITUTION.

Exit status: 0 when every file matches (bytes, or leaves after the named
ignores), 1 otherwise.
"""

from __future__ import annotations

import argparse
import csv
import hashlib
import io
import json
import re
import subprocess
import sys
from pathlib import Path
from typing import Any


def git_blob(repo: Path, rev: str, path: str) -> bytes | None:
    """Return the bytes of ``rev:path`` in ``repo``, or None when absent."""
    proc = subprocess.run(
        ["git", "-C", str(repo), "show", f"{rev}:{path}"],
        capture_output=True, check=False,
    )
    return proc.stdout if proc.returncode == 0 else None


def git_blob_id(repo: Path, rev: str, path: str) -> str | None:
    """Return the blob id of ``rev:path``, or None when absent."""
    proc = subprocess.run(
        ["git", "-C", str(repo), "rev-parse", f"{rev}:{path}"],
        capture_output=True, text=True, check=False,
    )
    return proc.stdout.strip() if proc.returncode == 0 else None


def leaves(obj: Any, prefix: str = "") -> dict[str, Any]:
    """Flatten a JSON value to ``{path: scalar}``; list indices are kept."""
    out: dict[str, Any] = {}
    if isinstance(obj, dict):
        if not obj:
            out[prefix or "$"] = {}
        for key, value in obj.items():
            out.update(leaves(value, f"{prefix}.{key}" if prefix else str(key)))
    elif isinstance(obj, list):
        if not obj:
            out[prefix or "$"] = []
        for index, value in enumerate(obj):
            out.update(leaves(value, f"{prefix}[{index}]"))
    else:
        out[prefix or "$"] = obj
    return out


def key_order(obj: Any, prefix: str = "") -> list[str]:
    """List every dict key path in document order (detects order-only diffs)."""
    out: list[str] = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            path = f"{prefix}.{key}" if prefix else str(key)
            out.append(path)
            out.extend(key_order(value, path))
    elif isinstance(obj, list):
        for index, value in enumerate(obj):
            out.extend(key_order(value, f"{prefix}[{index}]"))
    return out


def compare_json(new: bytes, old: bytes, ignore: list[re.Pattern]) -> dict:
    """Leaf-by-leaf comparison of two JSON documents."""
    a, b = leaves(json.loads(new)), leaves(json.loads(old))
    ignored, differing = [], []
    for path in sorted(set(a) | set(b)):
        va, vb = a.get(path, "<absent>"), b.get(path, "<absent>")
        if va == vb and type(va) is type(vb):
            continue
        last = re.sub(r"\[\d+\]", "", path.rsplit(".", 1)[-1])
        if any(p.search(path) or p.search(last) for p in ignore):
            ignored.append(path)
        else:
            differing.append({"path": path, "regenerated": va, "committed": vb})
    order_same = key_order(json.loads(new)) == key_order(json.loads(old))
    return {"kind": "json", "n_leaves": len(b), "n_differing": len(differing),
            "differing": differing[:50], "n_ignored": len(ignored),
            "ignored": ignored[:50], "key_order_identical": order_same}


def compare_csv(new: bytes, old: bytes) -> dict:
    """Cell-by-cell comparison of two CSV files."""
    a = list(csv.reader(io.StringIO(new.decode())))
    b = list(csv.reader(io.StringIO(old.decode())))
    diffs = []
    for i in range(max(len(a), len(b))):
        ra = a[i] if i < len(a) else None
        rb = b[i] if i < len(b) else None
        if ra != rb:
            diffs.append({"row": i, "regenerated": ra, "committed": rb})
    return {"kind": "csv", "n_rows": len(b), "n_differing": len(diffs),
            "differing": diffs[:30]}


def compare_text(new: bytes, old: bytes, ignore: list[re.Pattern]) -> dict:
    """Line-by-line comparison; lines matching an ignore regex are set aside."""
    a = new.decode(errors="replace").splitlines()
    b = old.decode(errors="replace").splitlines()
    diffs, ignored = [], []
    for i in range(max(len(a), len(b))):
        la = a[i] if i < len(a) else None
        lb = b[i] if i < len(b) else None
        if la == lb:
            continue
        if la is not None and lb is not None and any(
                p.search(la) and p.search(lb) for p in ignore):
            ignored.append(i + 1)
        else:
            diffs.append({"line": i + 1, "regenerated": la, "committed": lb})
    return {"kind": "text", "n_lines": len(b), "n_differing": len(diffs),
            "differing": diffs[:30], "n_ignored": len(ignored),
            "ignored_lines": ignored[:30]}


def main() -> int:
    """Compare every requested path and write a JSON report."""
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--repo", type=Path, required=True,
                    help="any checkout of the repository (for git show)")
    ap.add_argument("--tree", type=Path, required=True,
                    help="root the regenerated files sit under")
    ap.add_argument("--commit", required=True, help="generating commit")
    ap.add_argument("--today", default="origin/main",
                    help="revision standing for today's file")
    ap.add_argument("--ignore-key", action="append", default=[],
                    help="regex for JSON leaf keys or text lines to set aside")
    ap.add_argument("--substitute", action="append", default=[],
                    help="OLD=NEW byte substitution applied to regenerated files")
    ap.add_argument("--paths", nargs="*", default=[])
    ap.add_argument("--paths-file", type=Path)
    ap.add_argument("--out", type=Path, required=True)
    args = ap.parse_args()

    paths = list(args.paths)
    if args.paths_file:
        paths += [p.strip() for p in args.paths_file.read_text().splitlines()
                  if p.strip()]
    ignore = [re.compile(p) for p in args.ignore_key]
    records, all_ok = [], True
    for path in paths:
        rec: dict[str, Any] = {"path": path}
        old = git_blob(args.repo, args.commit, path)
        new_path = args.tree / path
        if old is None or not new_path.exists():
            rec["status"] = "MISSING-" + ("COMMITTED" if old is None else "REGENERATED")
            all_ok = False
            records.append(rec)
            continue
        new = new_path.read_bytes()
        rec["sha256_regenerated"] = hashlib.sha256(new).hexdigest()
        substituted = new
        for pair in args.substitute:
            old_text, new_text = pair.split("=", 1)
            substituted = substituted.replace(old_text.encode(), new_text.encode())
        rec["sha256_committed"] = hashlib.sha256(old).hexdigest()
        gen_blob = git_blob_id(args.repo, args.commit, path)
        today_blob = git_blob_id(args.repo, args.today, path)
        rec["today_is_generating_blob"] = gen_blob == today_blob
        if new == old:
            rec["status"] = "BYTE-IDENTICAL"
        elif substituted == old:
            rec["status"] = "BYTE-IDENTICAL-AFTER-SUBSTITUTION"
        else:
            new = substituted
            if path.endswith((".json", ".geojson")):
                detail = compare_json(new, old, ignore)
            elif path.endswith(".csv"):
                detail = compare_csv(new, old)
            else:
                detail = compare_text(new, old, ignore)
            rec["detail"] = detail
            rec["status"] = ("EQUAL-AFTER-IGNORES" if detail["n_differing"] == 0
                             else "DIFFERS")
            all_ok &= detail["n_differing"] == 0
        records.append(rec)
    counts: dict[str, int] = {}
    for rec in records:
        counts[rec["status"]] = counts.get(rec["status"], 0) + 1
    report = {"commit": args.commit, "tree": str(args.tree),
              "ignore_key": args.ignore_key, "substitute": args.substitute, "n_files": len(records),
              "counts": counts,
              "n_today_is_generating_blob": sum(
                  1 for r in records if r.get("today_is_generating_blob")),
              "files": records}
    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text(json.dumps(report, indent=2) + "\n")
    print(json.dumps({"n_files": len(records), "counts": counts,
                      "n_today_is_generating_blob":
                          report["n_today_is_generating_blob"]}))
    return 0 if all_ok else 1


if __name__ == "__main__":
    sys.exit(main())
